```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Elastic Beanstalk EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier",
    "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWorkerTier",
    "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
  ]
}

# Instance Profile associated with the IAM role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_application" {
  name = "my_application"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "my_environment" {
  name                = "my_environment"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v3.4.1 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name
}
```

This Terraform configuration does the following:
1. Sets up the AWS provider with a specified region.
2. Creates an IAM role (`eb_ec2_role`) with policies necessary for Elastic Beanstalk operations.
3. Creates an IAM instance profile (`eb_ec2_profile`) associated with the IAM role.
4. Creates an Elastic Beanstalk application (`my_application`).
5. Creates an Elastic Beanstalk environment (`my_environment`) associated with the application, using the specified solution stack and instance profile.

