### Description
This Terraform configuration sets up an Elastic Beanstalk environment with autoscaling settings based on CPU utilization. It also connects the environment to an RDS database. The configuration includes the creation of an IAM role and instance profile for the EC2 instances in the Elastic Beanstalk environment. The RDS database is configured with a parameter group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EC2 instances in Elastic Beanstalk environment
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "eb_ec2_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "elasticbeanstalk:*",
            "ec2:*",
            "autoscaling:*",
            "cloudwatch:*",
            "logs:*",
            "rds:*"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

# IAM Instance Profile for EC2 instances in Elastic Beanstalk environment
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
}

# Add IAM role to instance profile
resource "aws_iam_instance_profile_roles" "add_role_to_instance_profile" {
  instance_profile = aws_iam_instance_profile.eb_ec2_profile.name
  roles            = [aws_iam_role.eb_ec2_role.name]
}

# Parameter group for RDS database
resource "aws_db_parameter_group" "db_param_group" {
  name   = "my_db1_param_group"
  family = "mysql8.0"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_unicode_ci"
  }
}

# RDS database instance
resource "aws_db_instance" "my_db1" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine         = "mysql"
  engine_version = "8.0"
  username       = "admin"
  password       = "securepassword"
  parameter_group_name = aws_db_parameter_group.db_param_group.name
  skip_final_snapshot = true
}

# Auto Scaling Group for Elastic Beanstalk environment
resource "aws_autoscaling_group" "eb_asg" {
  name                 = "eb_asg"
  launch_configuration = "eb-launch-config"
  min_size             = 1
  max_size             = 3
  desired_capacity     = 2
  vpc_zone_identifier  = ["subnet-12345678", "subnet-87654321"]

  tag {
    key                 = "Name"
    value               = "eb-asg-instance"
    propagate_at_launch = true
  }

  # Health check settings
  health_check_type        = "EC2"
  health_check_grace_period = 300

  # Lifecycle hooks
  initial_lifecycle_hook {
    name                 = "before-signal"
    default_result       = "CONTINUE"
    heartbeat_timeout    = 300
    lifecycle_transition = "autoscaling:EC2_INSTANCE_LAUNCHING"
  }

  # Scaling policies
  scaling_policy {
    name                   = "scale-up-policy"
    adjustment_type        = "ChangeInCapacity"
    scaling_adjustment     = 1
    cooldown               = 300
    metric_aggregation_type = "Average"

    alarm_configuration {
      alarms = ["HighCPUUtilization"]
    }
  }

  scaling_policy {
    name                   = "scale-down-policy"
    adjustment_type        = "ChangeInCapacity"
    scaling_adjustment     = -1
    cooldown               = 300
    metric_aggregation_type = "Average"

    alarm_configuration {
      alarms = ["LowCPUUtilization"]
    }
  }

  # CloudWatch Alarms
  alarm {
    name          = "HighCPUUtilization"
    comparison_operator = "GreaterThanThreshold"
    evaluation_periods = 2
    metric_name     = "CPUUtilization"
    namespace       = "AWS/EC2"
    period          = 120
    statistic       = "Average"
    threshold       = 80

    dimensions = {
      AutoScalingGroupName = aws_autoscaling_group.eb_asg.name
    }

    alarm_actions = [aws_autoscaling_group.eb_asg.scaling_policy[0].arn]
  }

  alarm {
    name          = "LowCPUUtilization"
    comparison_operator = "LessThanThreshold"
    evaluation_periods = 2
    metric_name     = "CPUUtilization"
    namespace       = "AWS/EC2"
    period          = 120
    statistic       = "Average"
    threshold       = 20

    dimensions = {
      AutoScalingGroupName = aws_autoscaling_group.eb_asg.name
    }

    alarm_actions = [aws_autoscaling_group.eb_asg.scaling_policy[1].arn]
  }
}
