```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "elastic_beanstalk_role" {
  name = "elastic_beanstalk_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "elastic_beanstalk_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "elasticbeanstalk:*",
            "ec2:*",
            "ecs:*",
            "autoscaling:*",
            "cloudwatch:*",
            "logs:*",
            "rds:*"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

# IAM Instance Profile for Elastic Beanstalk
resource "aws_iam_instance_profile" "elastic_beanstalk_instance_profile" {
  name = "elastic_beanstalk_instance_profile"
  roles = [aws_iam_role.elastic_beanstalk_role.name]
}

# VPC
resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Internet Gateway
resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
}

# Public Subnets
resource "aws_subnet" "public_subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  map_public_ip_on_launch = true
}

# Route Table
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main_vpc.id
}

# Route to Internet Gateway
resource "aws_route" "internet_gateway_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main_igw.id
}

# Route Table Associations
resource "aws_route_table_association" "public_subnet_a_assoc" {
  subnet_id      = aws_subnet.public_subnet_a.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "public_subnet_b_assoc" {
  subnet_id      = aws_subnet.public_subnet_b.id
  route_table_id = aws_route_table.public_route_table.id
}

# RDS Instance
resource "aws_db_instance" "web_app_db" {
  identifier              = "web-app-db"
  instance_class          = "db.t3.micro"
  allocated_storage       = 20
  engine                  = "mysql"
  engine_version          = "8.0"
  username                = "admin"
  password                = "password"
  skip_final_snapshot     = true
  vpc_security_group_ids  = [aws_security_group.db_sg.id]
  db_subnet_group_name    = aws_db_subnet_group.db_subnet_group.name
}

# Security Group for RDS
resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Security group for RDS"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "web-app-db-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_a.id, aws_subnet.public_subnet_b.id]
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "web_app_application" {
  name        = "web-app-application"
  description = "Application for web app"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "web_app_environment" {
  name                = "web-app-environment"
  application         = aws_elastic_beanstalk_application.web_app_application.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.elastic_beanstalk_instance_profile.name
}
