### Description

This Terraform configuration sets up an Elastic Beanstalk application along with its configuration template and environment. It includes the necessary IAM roles, VPC, and subnet configurations to support the Elastic Beanstalk environment. The configuration ensures that all resources are properly linked and dependent on each other as required.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "BeanstalkServiceRole"
  }
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name = "my-elastic-beanstalk-app"

  appversion_lifecycle {
    service_role          = aws_iam_role.beanstalk_service_role.arn
    max_count             = 128
    delete_source_from_s3 = true
  }

  tags = {
    Name = "MyElasticBeanstalkApp"
  }
}

# VPC and Subnet for Elastic Beanstalk Environment
resource "aws_vpc" "main_vpc" {
  cidr_block       = "10.0.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "MainSubnet"
  }
}

# Elastic Beanstalk Configuration Template
resource "aws_elastic_beanstalk_configuration_template" "elastic_beanstalk_config_template" {
  name                = "my-elastic-beanstalk-config-template"
  application         = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  tags = {
    Name = "MyElasticBeanstalkConfigTemplate"
  }
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "elastic_beanstalk_env" {
  name                = "my-elastic-beanstalk-env"
  application         = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  template_name       = aws_elastic_beanstalk_configuration_template.elastic_beanstalk_config_template.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main_vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = aws_subnet.main_subnet.id
  }

  tags = {
    Name = "MyElasticBeanstalkEnv"
  }
}
```

This Terraform configuration creates an Elastic Beanstalk application, a configuration template, and an environment, along with the necessary IAM roles, VPC, and subnet configurations. The resources are properly linked and dependent on each other as required.

