### Description
This Terraform configuration sets up an Elastic Beanstalk application running a version of Go. It includes the creation of an Elastic Beanstalk application, an S3 bucket to store the application version source bundle, an S3 object representing the application version, an Elastic Beanstalk application version, a configuration template, and an environment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "beanstalk_service" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "beanstalk_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
  role       = aws_iam_role.beanstalk_service.name
}

resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name        = "go-app"
  description = "Elastic Beanstalk application for Go"

  appversion_lifecycle {
    service_role          = aws_iam_role.beanstalk_service.arn
    max_count             = 128
    delete_source_from_s3 = true
  }
}

resource "aws_s3_bucket" "elastic_beanstalk_bucket" {
  bucket = "go-app-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "elastic_beanstalk_app_version" {
  bucket = aws_s3_bucket.elastic_beanstalk_bucket.id
  key    = "go-app-version.zip"
  source = "path/to/go-app-version.zip"
}

resource "aws_elastic_beanstalk_application_version" "elastic_beanstalk_app_version" {
  name        = "go-app-version-1"
  application = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  bucket      = aws_s3_bucket.elastic_beanstalk_bucket.id
  key         = aws_s3_object.elastic_beanstalk_app_version.key
}

resource "aws_elastic_beanstalk_configuration_template" "elastic_beanstalk_config_template" {
  name                = "go-app-template"
  application         = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Go 1.17"
}

resource "aws_elastic_beanstalk_environment" "elastic_beanstalk_env" {
  name                = "go-app-env"
  application         = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Go 1.17"
  version_label       = aws_elastic_beanstalk_application_version.elastic_beanstalk_app_version.name
  template_name       = aws_elastic_beanstalk_configuration_template.elastic_beanstalk_config_template.name
}
```

### Explanation
1. **Provider Configuration**: Sets the AWS region to `us-west-2`.
2. **IAM Role and Policy Attachment**: Creates an IAM role for Elastic Beanstalk and attaches the necessary policy.
3. **Elastic Beanstalk Application**: Creates an Elastic Beanstalk application with a lifecycle policy.
4. **S3 Bucket and Object**: Creates an S3 bucket and uploads the Go application version source bundle.
5. **Elastic Beanstalk Application Version**: Creates an application version linked to the S3 object.
6. **Elastic Beanstalk Configuration Template**: Creates a configuration template based on a compatible solution stack.
7. **Elastic Beanstalk Environment**: Deploys the application version to an environment using the configuration template.

