resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "BeanstalkServiceRole"
  }
}

# S3 Bucket for storing application version
resource "aws_s3_bucket" "elastic_beanstalk_bucket" {
  bucket = "elastic-beanstalk-app-version-bucket-${random_string.suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    enabled = true
    max_age_in_days = 5
  }

  tags = {
    Name = "ElasticBeanstalkAppVersionBucket"
  }
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# S3 Object containing the application version
resource "aws_s3_object" "elastic_beanstalk_app_version" {
  bucket = aws_s3_bucket.elastic_beanstalk_bucket.id
  key    = "app-version.zip"
  source = "path/to/app-version.zip"

  tags = {
    Name = "ElasticBeanstalkAppVersionObject"
  }
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name        = "my-elastic-beanstalk-app"
  description = "My Elastic Beanstalk Application"

  appversion_lifecycle {
    service_role          = aws_iam_role.beanstalk_service_role.arn
    max_age_in_days       = 5
    delete_source_from_s3 = true
  }

  tags = {
    Name = "MyElasticBeanstalkApplication"
  }
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "elastic_beanstalk_app_version" {
  name        = "v1"
  application = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  bucket      = aws_s3_bucket.elastic_beanstalk_bucket.id
  key         = aws_s3_object.elastic_beanstalk_app_version.key

  tags = {
    Name = "MyElasticBeanstalkAppVersion"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `beanstalk-service-role` is created with a trust policy allowing Elastic Beanstalk to assume the role.
3. **S3 Bucket**: An S3 bucket named `elastic-beanstalk-app-version-bucket-{random_suffix}` is created with versioning enabled and a lifecycle rule to delete objects after 5 days.
4. **Random String**: A random string is generated to ensure the S3 bucket name is unique.
5. **S3 Object**: An S3 object named `app-version.zip` is uploaded to the S3 bucket.
6. **Elastic Beanstalk Application**: An Elastic Beanstalk application named `my-elastic-beanstalk-app` is created with an application version lifecycle that retains versions for 5 days and deletes them from S3.
7. **Elastic Beanstalk Application Version**: An application version named `v1` is created and associated with the Elastic Beanstalk application and the S3 object.

