### Terraform Program Description

This Terraform program creates an AWS CodeBuild project with the following components:
1. **IAM Role**: An IAM role with the necessary permissions for CodeBuild operations.
2. **CodeBuild Project**: A CodeBuild project configured with a GitHub source, an artifact, and a cache.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_example_role" {
  name = "codebuild-example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy"
  description = "Policy for CodeBuild operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "s3:*",
          "ec2:CreateNetworkInterface",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:CreateNetworkInterfacePermission",
          "codeconnections:GetConnectionToken",
          "codeconnections:GetConnection"
        ]
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attach" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_example_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "codebuild_example_project" {
  name         = "codebuild-example-project"
  description  = "Example CodeBuild project"
  service_role = aws_iam_role.codebuild_example_role.arn

  artifacts {
    type = "S3"
  }

  cache {
    type     = "S3"
    location = "codebuild-artifacts-bucket"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  tags = {
    Environment = "Example"
  }
}
```

