This Terraform configuration creates an AWS CodeBuild project with an example IAM role and secondary sources. The IAM role is configured with the necessary permissions for CodeBuild operations. The CodeBuild project is set up to use a GitHub repository as the primary source and another GitHub repository as a secondary source.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "example_codebuild_role" {
  name = "example_codebuild_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "CodeBuildPolicy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
            "ec2:CreateNetworkInterface",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeVpcs",
            "ec2:CreateNetworkInterfacePermission",
            "s3:*",
            "codeconnections:GetConnectionToken",
            "codeconnections:GetConnection"
          ]
          Resource = "*"
        },
      ]
    })
  }
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild Project"
  service_role  = aws_iam_role.example_codebuild_role.arn
  build_timeout = 5

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:4.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/user/repo1.git"
    git_clone_depth = 1
  }

  secondary_sources {
    source_identifier = "secondary-source"
    type            = "GITHUB"
    location        = "https://github.com/user/repo2.git"
    git_clone_depth = 1
  }

  secondary_source_version {
    source_identifier = "secondary-source"
    source_version    = "main"
  }

  tags = {
    Environment = "Test"
  }
}
```

