### Description

This Terraform program creates an AWS Lex bot for ordering pizza with a follow-up question. The bot includes an intent for ordering pizza, which triggers a Lambda function for fulfillment. The intent also includes a follow-up prompt to ask for additional information.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Function
resource "aws_iam_role" "pizza_order_lambda_role" {
  name = "pizza_order_lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Function
resource "aws_iam_policy" "pizza_order_lambda_policy" {
  name        = "pizza_order_lambda_policy"
  description = "Policy for Lambda function to access necessary resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "pizza_order_lambda_policy_attach" {
  policy_arn = aws_iam_policy.pizza_order_lambda_policy.arn
  role       = aws_iam_role.pizza_order_lambda_role.name
}

# Lambda Function for Fulfillment
resource "aws_lambda_function" "pizza_order_lambda" {
  function_name = "pizza_order_lambda"
  role          = aws_iam_role.pizza_order_lambda_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  filename         = "lambda_function_payload.zip"
  source_code_hash = filebase64sha256("lambda_function_payload.zip")
}

# AWS Lex Intent for Ordering Pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name           = "OrderPizza"
  description    = "Intent to order a pizza"
  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order me a pizza"
  ]

  dialog_code_hook {
    message_version = "1.0"
    uri             = aws_lambda_function.pizza_order_lambda.invoke_arn
  }

  fulfillment_activity {
    type = "CodeHook"
  }

  follow_up_prompt {
    prompt {
      max_attempts = 2
    }
  }
}

# AWS Lex Bot for Ordering Pizza
resource "aws_lex_bot" "order_pizza_bot" {
  name             = "OrderPizzaBot"
  child_directed   = false
  locale           = "en-US"
  process_behavior = "BUILD"
  voice_id         = "Joanna"

  abort_statement {
    message {
      content      = "Sorry, I am not able to assist at this time."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand you, what would you like to do?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.order_pizza_intent.name
    intent_version = "$LATEST"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role and Policy**: An IAM role and policy are created for the Lambda function to allow it to log to CloudWatch.
3. **Lambda Function**: A Lambda function is defined to handle the fulfillment of the pizza order intent.
4. **AWS Lex Intent**: An intent named `OrderPizza` is created with sample utterances and a dialog code hook that points to the Lambda function. It also includes a follow-up prompt.
5. **AWS Lex Bot**: A bot named `OrderPizzaBot` is created, which uses the `OrderPizza` intent. It includes abort and clarification prompts.

