Below is a complete Terraform HCL program that creates an AWS Lex bot for ordering pizzas, specifically tailored for kids. The program includes the necessary IAM role and intent configurations.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "lex.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_lex_intent" "order_pizza_intent" {
  name = "OrderPizza"

  sample_utterances = [
    "I want a pizza",
    "Can I have a pizza?",
    "Order a pizza please",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "order_pizza_bot" {
  name            = "OrderPizzaBot"
  child_directed  = true
  locale          = "en-US"
  idle_session_ttl_in_seconds = 300
  role_arn        = aws_iam_role.lex_bot_role.arn

  intent {
    intent_name    = aws_lex_intent.order_pizza_intent.name
    intent_version = "$LATEST"
  }

  abort_statement {
    message {
      content      = "Sorry, I couldn't help with that."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content      = "I didn't understand that. Could you please repeat?"
      content_type = "PlainText"
    }
  }
}
```

