}

resource "aws_lex_intent" "order_pizza_intent" {
  name           = "OrderPizza"
  description    = "Intent to order a pizza"
  sample_utterances = [
    "I want a {PizzaSize} pizza",
    "Order {Quantity} {PizzaSize} pizzas"
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  confirmation_prompt {
    max_attempts = 2

    message {
      content      = "Okay, your {Quantity} {PizzaSize} pizza(s) will be ready. Does this sound okay?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I will not place your pizza order."
      content_type = "PlainText"
    }
  }

