    name            = "PizzaSize"
    slot_constraint = "Required"
    slot_type       = "AMAZON.LITERAL"

    sample_utterances = [
      "small",
      "medium",
      "large"
    ]

    value_elicitation_prompt {
      max_attempts = 2

      message {
        content      = "What size pizza would you like?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name            = "Quantity"
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"

    sample_utterances = [
      "one",
      "two",
      "three"
    ]

    value_elicitation_prompt {
      max_attempts = 2

