### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_connect_instance" "connect_instance" {
  identity_management_type = "SAML"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  instance_alias           = "my-connect-instance"
}

resource "aws_iam_role" "lex_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_lexv2models_bot" "lex_bot" {
  name                    = "my-lex-bot"
  idle_session_ttl_in_seconds = 300
  role_arn                = aws_iam_role.lex_role.arn

  data_privacy {
    child_directed = false
  }

  tags = {
    environment = "production"
  }
}

resource "aws_connect_bot_association" "connect_bot_association" {
  instance_id = aws_connect_instance.connect_instance.id

  lex_bot {
    name = aws_lexv2models_bot.lex_bot.name
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **AWS Connect Instance**: An AWS Connect instance is created with SAML identity management enabled.
3. **IAM Role for Lex Bot**: An IAM role is created for the AWS Lex bot with a trust policy allowing Lex to assume the role.
4. **AWS Lex Bot**: An AWS Lex bot is defined with a specified name, idle session TTL, and the IAM role ARN.
5. **Connect Bot Association**: The AWS Connect instance is associated with the AWS Lex bot using the `aws_connect_bot_association` resource.

