### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy" {
  role       = aws_iam_role.kinesis_analytics_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/KinesisAnalyticsforApacheFlinkServiceRolePolicy"
}

resource "aws_kinesisanalyticsv2_application" "flink_application" {
  name                   = "flink-application"
  runtime_environment    = "FLINK-1_19"
  service_execution_role = aws_iam_role.kinesis_analytics_role.arn

