This Terraform configuration sets up a Kinesis Firehose Delivery Stream with a Redshift cluster destination. It includes the creation of an IAM role with the necessary permissions, a Redshift cluster, and an S3 bucket for backup purposes. The Kinesis Firehose Delivery Stream is configured to deliver data to the Redshift cluster using the specified IAM role and S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "kinesis_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonKinesisFirehoseFullAccess",
    "arn:aws:iam::aws:policy/AmazonS3FullAccess",
    "arn:aws:iam::aws:policy/AmazonRedshiftFullAccess"
  ]
}

# Redshift Cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  database_name      = "mydatabase"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  node_type          = "dc2.large"
  cluster_type       = "single-node"
}

# S3 Bucket for Backup
resource "aws_s3_bucket" "backup_bucket" {
  bucket = "my-backup-bucket-${random_string.suffix.result}"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "my-kinesis-firehose-delivery-stream"
  destination = "redshift"

  redshift_configuration {
    role_arn           = aws_iam_role.firehose_role.arn
    cluster_jdbcurl    = "jdbc:redshift://${aws_redshift_cluster.redshift_cluster.endpoint}/${aws_redshift_cluster.redshift_cluster.database_name}"
    username           = "admin"
    password           = "SecurePassword123!"
    data_table_name    = "mytable"
    copy_options       = "delimiter '|'"
    data_table_columns = "column1,column2"
    s3_backup_mode     = "Enabled"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_size     = 10
      buffering_interval = 400
      compression_format = "GZIP"
    }
  }
}
```

This configuration ensures that the Kinesis Firehose Delivery Stream has the necessary permissions to access the Redshift cluster and the S3 bucket for backup. The IAM role is granted the appropriate policies to perform these actions. The Redshift cluster and S3 bucket are also created as part of the setup.

