### Description
This Terraform configuration creates a Kinesis Firehose Delivery Stream with an Elasticsearch destination. It includes the necessary IAM role and S3 bucket for backup configuration. The IAM role is granted the required permissions for Elasticsearch and S3 operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "kinesis_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "firehose_policy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "es:ESHttpPut",
            "es:ESHttpGet",
            "es:ESHttpPost",
            "es:ESHttpDelete",
            "es:ESHttpHead",
            "s3:AbortMultipartUpload",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = "*"
        },
      ]
    })
  }
}

# S3 Bucket for Backup Configuration
resource "aws_s3_bucket" "backup_bucket" {
  bucket = "kinesis-firehose-backup-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "KinesisFirehoseBackupBucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "kinesis_firehose_delivery_stream"
  destination = "elasticsearch"

  depends_on = [
    aws_iam_role.firehose_role,
    aws_s3_bucket.backup_bucket
  ]

  elasticsearch_configuration {
    domain_arn = "arn:aws:es:us-west-2:123456789012:domain/my-elasticsearch-domain"
    role_arn   = aws_iam_role.firehose_role.arn
    index_name = "my-index"
    type_name  = "_doc"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_size     = 5
      buffering_interval = 300
      compression_format = "GZIP"
    }
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `kinesis_firehose_role` is created with an assume role policy that allows Firehose to assume the role. The role has an inline policy granting permissions for Elasticsearch and S3 operations.
3. **S3 Bucket**: An S3 bucket named `kinesis-firehose-backup-bucket-<random_suffix>` is created for backup configuration. The bucket name is made unique using a random string suffix.
4. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose Delivery Stream is created with an Elasticsearch destination. The stream uses the IAM role and S3 bucket created earlier. The Elasticsearch configuration specifies the domain ARN, index name, and type name. The S3 configuration specifies the bucket ARN, buffering settings, and compression format.

