### Description
This Terraform configuration creates a Kinesis Firehose Delivery Stream with an HTTP endpoint destination, such as New Relic. It includes an IAM role with the necessary permissions and an S3 bucket for backup purposes.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "firehose_delivery_stream_policy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:AbortMultipartUpload",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = [
            aws_s3_bucket.backup_bucket.arn,
            "${aws_s3_bucket.backup_bucket.arn}/*"
          ]
        },
        {
          Action = [
            "logs:CreateLogDelivery",
            "logs:DescribeLogGroups",
            "logs:DescribeLogStreams",
            "logs:PutLogEvents",
            "logs:UpdateLogDelivery"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_s3_bucket" "backup_bucket" {
  bucket = "firehose-backup-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-delivery-stream"
  destination = "http_endpoint"

  http_endpoint_configuration {
    url                = "https://aws-api.newrelic.com/firehose/v1"
    name               = "New Relic"
    access_key         = "my-key"
    buffering_size     = 15
    buffering_interval = 600
    role_arn           = aws_iam_role.firehose_role.arn
    s3_backup_mode     = "FailedDataOnly"

    s3_configuration {
      role_arn           = aws_iam_role.firehose_role.arn
      bucket_arn         = aws_s3_bucket.backup_bucket.arn
      buffering_size     = 10
      buffering_interval = 400
      compression_format = "GZIP"
    }
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with the region `us-west-2`.
2. **IAM Role**: An IAM role named `firehose_delivery_stream_role` is created with a trust policy allowing Firehose to assume the role. The role has inline policies granting permissions to access the S3 bucket and write logs to CloudWatch.
3. **S3 Bucket**: An S3 bucket named `firehose-backup-bucket-<random_suffix>` is created for storing backup data. The bucket name is made unique using a random string suffix.
4. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose Delivery Stream is created with an HTTP endpoint destination. The stream is configured to send data to a New Relic endpoint and back up failed data to the S3 bucket. The HTTP endpoint configuration includes buffering settings and an S3 backup configuration.

