### Description
This Terraform configuration sets up a Kinesis Firehose Delivery Stream with an OpenSearch Serverless destination, including VPC configuration. It includes the necessary IAM roles, S3 bucket, and OpenSearch Serverless collection. The IAM role grants Firehose the permissions needed to access OpenSearch Serverless and S3, while the S3 bucket is configured to allow Firehose to write data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Firehose
resource "aws_iam_role" "firehose_role" {
  name = "firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "firehose-policy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "es:DescribeDomain",
            "es:DescribeDomains",
            "es:DescribeDomainConfig",
            "ec2:DescribeVpcs",
            "ec2:DescribeVpcAttribute",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeNetworkInterfaces",
            "ec2:CreateNetworkInterface",
            "ec2:CreateNetworkInterfacePermission",
            "ec2:DeleteNetworkInterface",
            "s3:AbortMultipartUpload",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

# S3 Bucket for Backup
resource "aws_s3_bucket" "backup_bucket" {
  bucket = "firehose-backup-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

# OpenSearch Serverless Collection
resource "aws_opensearchserverless_collection" "opensearch_collection" {
  name = "firehose-collection"
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-delivery-stream"
  destination = "opensearchserverless"

  opensearchserverless_configuration {
    collection_endpoint = aws_opensearchserverless_collection.opensearch_collection.collection_endpoint
    index_name        = "firehose-index"
    role_arn          = aws_iam_role.firehose_role.arn

    s3_configuration {
      bucket_arn = aws_s3_bucket.backup_bucket.arn
      role_arn   = aws_iam_role.firehose_role.arn
    }

    vpc_config {
      subnet_ids         = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
      security_group_ids = ["sg-0123456789abcdef0"]
      role_arn           = aws_iam_role.firehose_role.arn
    }
  }
}
```

### Explanation
1. **Provider Configuration**: Sets the AWS region to `us-west-2`.
2. **IAM Role**: Creates an IAM role named `firehose-role` with an assume role policy allowing Firehose to assume the role. It also attaches an inline policy granting necessary permissions for Firehose to access OpenSearch Serverless and S3.
3. **S3 Bucket**: Creates an S3 bucket named `firehose-backup-bucket-{random_suffix}` for storing backup data.
4. **OpenSearch Serverless Collection**: Creates an OpenSearch Serverless collection named `firehose-collection`.
5. **Kinesis Firehose Delivery Stream**: Configures a Kinesis Firehose Delivery Stream with an OpenSearch Serverless destination. It specifies the collection endpoint, index name, and IAM role ARN. The S3 configuration includes the backup bucket ARN and IAM role ARN. The VPC configuration specifies subnet IDs, security group IDs, and IAM role ARN for VPC access.

