### Description
This Terraform configuration creates a Kinesis Firehose Delivery Stream with an extended S3 Destination. It includes the necessary IAM role and S3 bucket resources to ensure proper access and configuration.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an S3 bucket for the Kinesis Firehose Delivery Stream
resource "aws_s3_bucket" "firehose_s3_bucket" {
  bucket = "my-kinesis-firehose-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "KinesisFirehoseBucket"
    Environment = "Production"
  }
}

# Generate a random suffix for the S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Create an IAM role for the Kinesis Firehose Delivery Stream
resource "aws_iam_role" "firehose_role" {
  name = "kinesis_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role to allow access to the S3 bucket
resource "aws_iam_role_policy" "firehose_s3_policy" {
  name = "kinesis_firehose_s3_policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.firehose_s3_bucket.arn,
          "${aws_s3_bucket.firehose_s3_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Create the Kinesis Firehose Delivery Stream with an extended S3 Destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "my-kinesis-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.firehose_s3_bucket.arn
    prefix     = "firehose-data/"
    buffering_interval = 300
    buffering_size = 5
    compression_format = "GZIP"
    s3_backup_mode = "FailedDataOnly"
  }
}
```

This configuration sets up a Kinesis Firehose Delivery Stream that delivers data to an S3 bucket. It includes an IAM role with the necessary permissions to access the S3 bucket. The S3 bucket is created with a unique name generated using a random string. The Kinesis Firehose Delivery Stream is configured with extended S3 settings, including buffering intervals, compression formats, and backup modes.

