### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Analytics
resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/KinesisAnalyticsforApacheFlinkExecutionRole",
    "arn:aws:iam::aws:policy/service-role/KinesisAnalyticsforSQLExecutionRole"
  ]
}

# CloudWatch Log Group and Stream for logging
resource "aws_cloudwatch_log_group" "sql_application_log_group" {
  name = "sql-application-log-group"
}

resource "aws_cloudwatch_log_stream" "sql_application_log_stream" {
  name           = "sql-application-log-stream"
  log_group_name = aws_cloudwatch_log_group.sql_application_log_group.name
}

# Kinesis Analytics V2 Application
resource "aws_kinesisanalyticsv2_application" "sql_application" {
  name                   = "sql-application"
  runtime_environment    = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics_role.arn

  application_configuration {
    application_code_configuration {
      code_content {
        text_content = "SELECT 1;"
      }

      code_content_type = "PLAINTEXT"
    }

    sql_application_configuration {
      input {
        name_prefix = "PREFIX_1"

        input_schema {
          record_column {
            name     = "COLUMN_1"
            sql_type = "VARCHAR(8)"
            mapping  = "MAPPING-1"
          }

          record_column {
            name     = "COLUMN_2"
            sql_type = "DOUBLE"
          }

          record_encoding = "UTF-8"

          record_format {
            record_format_type = "CSV"

            mapping_parameters {
              csv_mapping_parameters {
                record_column_delimiter = ","
                record_row_delimiter    = "\n"
              }
            }
          }
        }

        kinesis_streams_input {
          resource_arn = "arn:aws:kinesis:us-west-2:123456789012:stream/example-kinesis-stream"
        }
      }

      output {
        name = "OUTPUT_1"

        destination_schema {
          record_format_type = "JSON"
        }

        lambda_output {
          resource_arn = "arn:aws:lambda:us-west-2:123456789012:function/example-lambda-function"
        }
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.sql_application_log_stream.arn
  }
}
