### Description
This Terraform program creates an Amazon Kendra index and a data source associated with that index. The data source includes a proxy configuration that uses credentials stored in AWS Secrets Manager. The program also sets up an IAM role with the necessary permissions for Kendra and Secrets Manager.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for Kendra
resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role for Kendra and Secrets Manager
resource "aws_iam_role_policy" "kendra_role_policy" {
  name = "kendra-policy"
  role = aws_iam_role.kendra_role.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kendra:*",
          "secretsmanager:GetSecretValue"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Create a Kendra index
resource "aws_kendra_index" "kendra_index" {
  name     = "my-kendra-index"
  role_arn = aws_iam_role.kendra_role.arn

  tags = {
    Name = "MyKendraIndex"
  }
}

# Create a Secrets Manager secret for proxy credentials
resource "aws_secretsmanager_secret" "proxy_credentials_secret" {
  name = "kendra-proxy-credentials"
}

# Create a Kendra data source with a proxy configuration
resource "aws_kendra_data_source" "kendra_data_source" {
  index_id = aws_kendra_index.kendra_index.id
  name     = "my-kendra-data-source"
  type     = "WEBCRAWLER"
  role_arn = aws_iam_role.kendra_role.arn

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }
    }

    proxy_configuration {
      credentials = aws_secretsmanager_secret.proxy_credentials_secret.arn
    }
  }

  tags = {
    Name = "MyKendraDataSource"
  }
}
```

This Terraform configuration sets up the necessary resources to create a Kendra index and a data source with a proxy configuration. The IAM role and policy ensure that Kendra has the required permissions to access the index and retrieve proxy credentials from Secrets Manager.

