### Description
This Terraform configuration provisions an AWS EKS cluster named "example" with the specified IAM role and VPC settings. It includes dependencies on IAM role policy attachments for proper resource management during creation and deletion. The configuration also outputs the cluster's endpoint and the kubeconfig certificate authority data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

# Attach AmazonEKSClusterPolicy to the IAM role
resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

# Subnets for EKS Cluster
resource "aws_subnet" "eks_subnet_az1" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "eks_subnet_az2" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "eks_subnet_az3" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

# EKS Cluster
resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.eks_subnet_az1.id,
      aws_subnet.eks_subnet_az2.id,
      aws_subnet.eks_subnet_az3.id,
    ]
  }

  # Ensure that IAM Role permissions are created before and deleted
  # after EKS Cluster handling. Otherwise, EKS will not be able to
  # properly delete EKS managed EC2 infrastructure such as Security Groups.
  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy_attachment,
  ]
}

# Outputs
output "cluster_endpoint" {
  value = aws_eks_cluster.example.endpoint
}

output "kubeconfig_certificate_authority_data" {
  value = base64decode(aws_eks_cluster.example.certificate_authority[0].data)
}
```

### Notes
- Replace `"vpc-12345678"` with your actual VPC ID.
- Ensure that the subnets and VPC are already created and configured before applying this Terraform configuration.
- The `base64decode` function is used to decode the certificate authority data for the kubeconfig.

