### Description
This Terraform configuration sets up an AWS IAM role named `demo_eks` for an Amazon EKS cluster. The role allows assuming roles for EKS services and has policies attached for `AmazonEKSClusterPolicy` and `AmazonEKSVPCResourceController`. Additionally, it creates an AWS EKS cluster named `demo_eks` with specified VPC configurations. Proper dependency handling is ensured for IAM role permissions during cluster management.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the EKS cluster
resource "aws_iam_role" "demo_eks" {
  name = "demo_eks"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sts:AssumeRole",
          "sts:TagSession"
        ]
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

# Attach AmazonEKSClusterPolicy to the IAM role
resource "aws_iam_role_policy_attachment" "demo_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.demo_eks.name
}

# Attach AmazonEKSVPCResourceController to the IAM role
resource "aws_iam_role_policy_attachment" "demo_eks_vpc_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.demo_eks.name
}

# Create subnets for the EKS cluster
resource "aws_subnet" "subnet_az1" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

# Create an EKS cluster with specified VPC configurations
resource "aws_eks_cluster" "demo_eks" {
  name     = "demo_eks"
  role_arn = aws_iam_role.demo_eks.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
  }

  # Ensure that IAM Role permissions are created before and deleted
  # after EKS Cluster handling. Otherwise, EKS will not be able to
  # properly delete EKS managed EC2 infrastructure such as Security Groups.
  depends_on = [
    aws_iam_role_policy_attachment.demo_eks_cluster_policy,
    aws_iam_role_policy_attachment.demo_eks_vpc_policy,
  ]
}
```

### Notes
- Replace `"vpc-12345678"` with your actual VPC ID.
- Ensure that the subnets are in the correct availability zones and CIDR blocks for your VPC.
- The `depends_on` block ensures that the IAM role policies are attached before the EKS cluster is created.

