### Description
The Terraform program below creates an ElastiCache user with IAM authentication, an IAM user, and an ElastiCache user group. The ElastiCache user is associated with the IAM user, and the user group includes the ElastiCache user.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_user" "iam_user" {
  name = "elasticache-iam-user"
}

resource "aws_elasticache_user" "elasticache_user" {
  user_id       = "elasticache-user-id"
  user_name     = "elasticache-user-name"
  access_string = "on ~* +@all"
  engine        = "redis"

  authentication_mode {
    type = "iam"
  }
}

resource "aws_elasticache_user_group" "elasticache_user_group" {
  engine        = "redis"
  user_group_id = "elasticache-user-group-id"
  user_ids      = [aws_elasticache_user.elasticache_user.user_id]
}
