  subnet_id      = aws_subnet.subnet_private_1.id
}

resource "aws_efs_mount_target" "efs_mount_target_2" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.subnet_private_2.id
}

resource "aws_security_group" "security_group_private" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "aws_linux_instance_1" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.subnet_private_1.id
  security_groups = [aws_security_group.security_group_private.name]

  connection {
    type        = "ssh"
    user        = "ec2-user"
    private_key = file("~/.ssh/id_rsa")
  }

  provisioner "remote-exec" {
    inline = [
      "sudo yum install -y amazon-efs-utils",
      "sudo mkdir /mnt/efs",
      "sudo mount -t efs ${aws_efs_mount_target.efs_mount_target_1.dns_name}:/ /mnt/efs"
    ]
  }
}

resource "aws_instance" "aws_linux_instance_2" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.subnet_private_2.id
  security_groups = [aws_security_group.security_group_private.name]

  connection {
    type        = "ssh"
    user        = "ec2-user"
    private_key = file("~/.ssh/id_rsa")
  }

  provisioner "remote-exec" {
    inline = [
      "sudo yum install -y amazon-efs-utils",
      "sudo mkdir /mnt/efs",
      "sudo mount -t efs ${aws_efs_mount_target.efs_mount_target_2.dns_name}:/ /mnt/efs"
    ]
  }
}
