### Description
This Terraform configuration creates a DAX (DynamoDB Accelerator) cluster with the specified node type (`dax.r4.large`) and replication factor (`1`). It also sets up an IAM role and a parameter group required by the DAX cluster. The IAM role is granted permissions to access DynamoDB, and the parameter group is configured with default parameters.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify the desired AWS region
}

# Create an IAM role for the DAX cluster
resource "aws_iam_role" "dax_role" {
  name = "dax-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role to allow access to DynamoDB
resource "aws_iam_role_policy_attachment" "dax_dynamodb_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonDynamoDBFullAccess"
  role       = aws_iam_role.dax_role.name
}

# Create a DAX parameter group
resource "aws_dax_parameter_group" "dax_param_group" {
  name   = "dax-param-group"
  family = "DAX 1.0"

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "100000"
  }
}

# Create the DAX cluster
resource "aws_dax_cluster" "dax_cluster_example" {
  cluster_name       = "dax-cluster-example"
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  parameter_group_name = aws_dax_parameter_group.dax_param_group.name
}
```

This configuration sets up the necessary components to create a DAX cluster with the specified parameters. The IAM role is configured to allow the DAX service to access DynamoDB, and the parameter group is set with default parameters. The DAX cluster itself is created with the specified node type and replication factor.

