### Description
This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with 3 broker nodes in the `us-east-1` region. The configuration includes the creation of a VPC, three subnets in different availability zones, a security group, and the MSK cluster itself. The MSK cluster is configured with a specific Kafka version and instance type.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

data "aws_availability_zones" "azs" {
  state = "available"
}

resource "aws_subnet" "msk_subnet_az1" {
  availability_zone = data.aws_availability_zones.azs.names[0]
  cidr_block        = "10.0.1.0/24"
  vpc_id            = aws_vpc.msk_vpc.id
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "msk_subnet_az2" {
  availability_zone = data.aws_availability_zones.azs.names[1]
  cidr_block        = "10.0.2.0/24"
  vpc_id            = aws_vpc.msk_vpc.id
  tags = {
    Name = "msk-subnet-az2"
  }
}

resource "aws_subnet" "msk_subnet_az3" {
  availability_zone = data.aws_availability_zones.azs.names[2]
  cidr_block        = "10.0.3.0/24"
  vpc_id            = aws_vpc.msk_vpc.id
  tags = {
    Name = "msk-subnet-az3"
  }
}

resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.msk_vpc.id
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "msk-security-group"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.msk_subnet_az1.id,
      aws_subnet.msk_subnet_az2.id,
      aws_subnet.msk_subnet_az3.id,
    ]
    instance_type = "kafka.m5.large"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  tags = {
    Name = "my-msk-cluster"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Availability Zones**: The available availability zones in the `us-east-1` region are fetched.
4. **Subnet Creation**: Three subnets are created in different availability zones within the VPC.
5. **Security Group**: A security group is created to allow inbound traffic on port 9092 (Kafka) and all outbound traffic.
6. **MSK Cluster**: An MSK cluster is created with 3 broker nodes, using the specified Kafka version and instance type. The cluster is configured to use the created subnets and security group.

This configuration ensures that all dependencies are correctly established, and the MSK cluster is properly set up in the specified region.

