### Description
This Terraform configuration creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with JMX Exporter and Node Exporter enabled. The configuration includes the creation of subnets, a security group, and the MSK cluster itself. The MSK cluster is configured to use three subnets across different availability zones and is secured by the specified security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

# Create subnets in different availability zones
resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "msk-subnet-az2"
  }
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
  tags = {
    Name = "msk-subnet-az3"
  }
}

# Create a security group for the MSK cluster
resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.main.id
  name   = "msk-security-group"

  ingress {
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# Create the MSK cluster
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id,
    ]
    instance_type = "kafka.m5.large"
    security_groups = [
      aws_security_group.msk_security_group.id,
    ]
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}
```

This configuration sets up a basic MSK cluster with JMX Exporter and Node Exporter enabled. Adjust the `cidr_block`, `availability_zone`, and other parameters as needed for your specific environment.

