### Description

This Terraform configuration creates a serverless MSK cluster in the `us-east-1` region. It includes the necessary VPC, subnets, and security group configurations required for the MSK cluster to operate. The configuration ensures that the MSK cluster is properly set up with the specified subnets and security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_subnet" "msk_subnet_az1" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "msk_subnet_az2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags = {
    Name = "msk-subnet-az2"
  }
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.msk_vpc.id
  name   = "msk-sg"

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-sg"
  }
}

resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = "my-msk-serverless-cluster"

  vpc_config {
    subnet_ids         = [aws_subnet.msk_subnet_az1.id, aws_subnet.msk_subnet_az2.id]
    security_group_ids = [aws_security_group.msk_sg.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  tags = {
    Name = "my-msk-serverless-cluster"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnets**: Two subnets are created within the VPC, each in a different availability zone.
4. **Security Group**: A security group is created to allow inbound traffic on port 9098 (commonly used for Kafka) and all outbound traffic.
5. **MSK Serverless Cluster**: A serverless MSK cluster is created with the specified subnets and security group. Client authentication is configured using IAM.

This configuration ensures that the MSK cluster is properly set up in the specified region with the necessary network configurations.

