### Description
This Terraform configuration creates a serverless Amazon MSK (Managed Streaming for Apache Kafka) cluster with 3 broker nodes. The configuration includes the creation of a VPC, three subnets in different availability zones, a security group, and the MSK serverless cluster itself. The security group is configured to allow necessary traffic for the MSK cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Retrieve available availability zones
data "aws_availability_zones" "azs" {
  state = "available"
}

# Create three subnets in different availability zones
resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.azs.names[0]
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.azs.names[1]
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = data.aws_availability_zones.azs.names[2]
}

# Create a security group for the MSK cluster
resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "msk-security-group"

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create the MSK serverless cluster
resource "aws_msk_serverless_cluster" "msk_serverless" {
  cluster_name = "my-msk-serverless-cluster"

  vpc_config {
    subnet_ids         = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    security_group_ids = [aws_security_group.msk_sg.id]
  }
}
```

