  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "msk_subnet_az2" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "msk_subnet_az3" {
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

# Create a security group for the MSK cluster
resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [
      aws_subnet.msk_subnet_az1.id,
      aws_subnet.msk_subnet_az2.id,
      aws_subnet.msk_subnet_az3.id,
    ]
    instance_type = "m5.large"
    security_groups = [
      aws_security_group.msk_security_group.id,
    ]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_delivery_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_s3_bucket.id
        prefix  = "logs/msk/"
      }
    }
  }
}

# Create a CloudWatch log group for MSK broker logs
resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name = "msk-broker-logs"
}

# Create an S3 bucket for MSK broker logs
resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = "msk-broker-logs-bucket-${random_string.suffix.result}"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Create an IAM role for Kinesis Firehose
data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "firehose_role" {
  name               = "firehose-msk-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json
}

# Create a Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name        = "msk-broker-logs-delivery-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.msk_s3_bucket.arn
  }
}
