    type = "S"
  }
}

resource "aws_dynamodb_table" "dynamodb_table_us_west_2" {
  provider = aws.us_west_2

  name           = "myDynamoDBTable"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "myAttribute"
  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "myAttribute"
    type = "S"
  }
}

resource "aws_dynamodb_global_table" "dynamodb_global_table" {
  depends_on = [
    aws_dynamodb_table.dynamodb_table_us_west_1,
    aws_dynamodb_table.dynamodb_table_us_west_2,
  ]

  name = "myDynamoDBTable"

