### Description
This Terraform configuration creates a DAX (DynamoDB Accelerator) cluster. It includes the necessary IAM role and parameter group required by the DAX cluster. The IAM role is configured with a basic assume role policy that allows it to assume the role and access DynamoDB. The parameter group is also created with some default parameters.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for DAX
resource "aws_iam_role" "dax_role" {
  name = "dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for DAX to access DynamoDB
resource "aws_iam_policy" "dax_policy" {
  name        = "dax-policy"
  description = "Policy for DAX to access DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:*",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "dax_policy_attach" {
  role       = aws_iam_role.dax_role.name
  policy_arn = aws_iam_policy.dax_policy.arn
}

# DAX Parameter Group
resource "aws_dax_parameter_group" "dax_param_group" {
  name = "dax-param-group"

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "100000"
  }
}

# DAX Cluster
resource "aws_dax_cluster" "dax_cluster_example" {
  cluster_name       = "dax-cluster-example"
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  parameter_group_name = aws_dax_parameter_group.dax_param_group.name
}
```

This configuration sets up a DAX cluster with the necessary IAM role and parameter group. The IAM role is granted permissions to access DynamoDB, and the parameter group is configured with default settings. The DAX cluster is then created with these resources.

