This Terraform configuration sets up a basic AWS Neptune cluster with a custom parameter group. It includes the following resources:

1. **aws_neptune_cluster**: The main Neptune cluster resource.
2. **aws_neptune_cluster_instance**: An instance of the Neptune cluster.
3. **aws_neptune_cluster_parameter_group**: A custom parameter group for the Neptune cluster.
4. **aws_neptune_subnet_group**: A subnet group for the Neptune cluster.
5. **aws_neptune_parameter_group**: A parameter group for the Neptune instance.

The configuration ensures that the Neptune cluster and instance use the specified subnet group and parameter groups, and it sets up a basic structure for managing Neptune resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a Neptune subnet group
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]

  tags = {
    Name = "Neptune Subnet Group"
  }
}

# Define a custom Neptune cluster parameter group
resource "aws_neptune_cluster_parameter_group" "neptune_cluster_parameter_group" {
  family = "neptune1"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  tags = {
    Name = "Neptune Cluster Parameter Group"
  }
}

# Define a Neptune cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster-demo"
  engine                              = "neptune"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
  skip_final_snapshot                 = true
  iam_database_authentication_enabled = true
  apply_immediately                   = true
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.name
  neptune_subnet_group_name           = aws_neptune_subnet_group.name

  tags = {
    Name = "Neptune Cluster"
  }
}

# Define a Neptune cluster instance
resource "aws_neptune_cluster_instance" "neptune_cluster_instance" {
  cluster_identifier = aws_neptune_cluster.neptune_cluster.id
  instance_class     = "db.r4.large"
  apply_immediately  = true
  neptune_subnet_group_name = aws_neptune_subnet_group.name

  tags = {
    Name = "Neptune Cluster Instance"
  }
}
```

