### Description

This Terraform configuration sets up a basic AWS Neptune cluster with a custom parameter group and an instance in that cluster with its own custom parameter group. The configuration includes the necessary resources such as `aws_neptune_cluster`, `aws_neptune_cluster_instance`, `aws_neptune_cluster_parameter_group`, `aws_neptune_parameter_group`, and `aws_neptune_subnet_group`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Subnet Group
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  tags = {
    Name = "Neptune Subnet Group"
  }
}

# Cluster Parameter Group
resource "aws_neptune_cluster_parameter_group" "neptune_cluster_parameter_group" {
  family = "neptune1"
  name   = "custom-neptune-cluster-param-group"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }
}

# Instance Parameter Group
resource "aws_neptune_parameter_group" "neptune_instance_parameter_group" {
  family = "neptune1"
  name   = "custom-neptune-instance-param-group"

  parameter {
    name  = "neptune_query_timeout"
    value = "25"
  }
}

# Neptune Cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster-demo"
  engine                              = "neptune"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
  skip_final_snapshot                 = true
  iam_database_authentication_enabled = true
  apply_immediately                   = true
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.neptune_cluster_parameter_group.name
  neptune_subnet_group_name           = aws_neptune_subnet_group.neptune_subnet_group.name
  tags = {
    Name = "Neptune Cluster"
  }
}

# Neptune Cluster Instance
resource "aws_neptune_cluster_instance" "neptune_cluster_instance" {
  cluster_identifier         = aws_neptune_cluster.neptune_cluster.id
  engine                     = "neptune"
  instance_class             = "db.r5.large"
  apply_immediately          = true
  neptune_parameter_group_name = aws_neptune_parameter_group.neptune_instance_parameter_group.name
  neptune_subnet_group_name    = aws_neptune_subnet_group.neptune_subnet_group.name
  tags = {
    Name = "Neptune Cluster Instance"
  }
}
```

