```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create a subnet
resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a Neptune subnet group
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = [aws_subnet.example.id]
}

# Create a Neptune security group
resource "aws_security_group" "neptune_sg" {
  name        = "neptune-sg"
  description = "Security group for Neptune instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = ["10.0.1.0/24"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM role for Neptune
resource "aws_iam_role" "neptune_iam_role" {
  name = "neptune-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "neptune.amazonaws.com"
        }
      },
    ]
  })
}

# Create a Neptune cluster parameter group
resource "aws_neptune_cluster_parameter_group" "neptune_cluster_param_group" {
  family = "neptune1"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }
}

# Create a Neptune instance parameter group
resource "aws_neptune_parameter_group" "neptune_instance_param_group" {
  family = "neptune1"

  parameter {
    name  = "neptune_query_timeout"
    value = "25"
  }
}

# Create a Neptune cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster-demo"
  engine                              = "neptune"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
  skip_final_snapshot                 = true
  iam_database_authentication_enabled = true
  apply_immediately                   = true
  neptune_subnet_group_name           = aws_neptune_subnet_group.neptune_subnet_group.name
  vpc_security_group_ids              = [aws_security_group.neptune_sg.id]
  iam_roles                           = [aws_iam_role.neptune_iam_role.arn]
  neptune_cluster_parameter_group_name = aws_neptune_cluster_param_group.name
  neptune_instance_parameter_group_name = aws_neptune_instance_param_group.name
}

# Create a Neptune instance
resource "aws_neptune_cluster_instance" "neptune_instance" {
  cluster_identifier = aws_neptune_cluster.neptune_cluster.id
  engine             = "neptune"
  instance_class     = "db.r5.large"
  apply_immediately  = true
  neptune_subnet_group_name = aws_neptune_subnet_group.neptune_subnet_group.name
  neptune_parameter_group_name = aws_neptune_instance_param_group.name
}
