Below is a complete Terraform HCL program that sets up an AWS CodeBuild project for an autograder, running students' code stored on GitHub and storing the results. The program includes the necessary IAM roles, VPC, subnet, and security group configurations.

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder_codebuild_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })

  inline_policy {
    name = "autograder_codebuild_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents",
          ]
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "ec2:CreateNetworkInterface",
            "ec2:DescribeDhcpOptions",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "ec2:DescribeVpcs",
          ]
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = "ec2:CreateNetworkInterfacePermission"
          Resource = "arn:aws:ec2:us-west-2:123456789012:network-interface/*"
          Condition = {
            StringEquals = {
              "ec2:Subnet" = [aws_subnet.autograder_subnet.arn]
              "ec2:AuthorizedService" = "codebuild.amazonaws.com"
            }
          }
        },
        {
          Effect = "Allow"
          Action = "s3:*"
          Resource = [
            "arn:aws:s3:::autograder-results-bucket",
            "arn:aws:s3:::autograder-results-bucket/*",
          ]
        },
        {
          Effect = "Allow"
          Action = [
            "codeconnections:GetConnectionToken",
            "codeconnections:GetConnection"
          ]
          Resource = "arn:aws:codestar-connections:us-west-2:123456789012:connection/guid-string"
        }
      ]
    })
  }
}

# VPC for CodeBuild
resource "aws_vpc" "autograder_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "autograder_vpc"
  }
}

# Subnet for CodeBuild
resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "autograder_subnet"
  }
}

# Security Group for CodeBuild
resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
