### Description
This Terraform configuration sets up an AWS service that runs a code every day at 7 UTC using AWS EventBridge. It includes the following components:
1. **IAM Role**: An IAM role with basic execution permissions for the Lambda function.
2. **Lambda Function**: A Lambda function that will execute the code.
3. **EventBridge Rule**: An EventBridge rule scheduled to trigger at 7 UTC every day.
4. **EventBridge Target**: A target that invokes the Lambda function when the EventBridge rule is triggered.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role Policy Attachment for Lambda Execution
resource "aws_iam_role_policy_attachment" "lambda_basic_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Lambda Function
resource "aws_lambda_function" "code_runner_lambda" {
  function_name = "daily_code_runner_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      LOG_LEVEL = "info"
    }
  }
}

# EventBridge Rule
resource "aws_cloudwatch_event_rule" "daily_code_runner" {
  name                = "daily_code_runner"
  schedule_expression = "cron(0 7 * * ? *)"
}

# EventBridge Target to Invoke Lambda Function
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_code_runner.name
  target_id = "RunDailyCode"
  arn       = aws_lambda_function.code_runner_lambda.arn

  input = jsonencode({
    key1 = "value1"
    key2 = "value2"
  })
}
```

