### Description

This Terraform configuration sets up the infrastructure for a video streaming site that distributes video content globally. It includes the following resources:

1. **AWS S3 Bucket**: To store the video content.
2. **AWS CloudFront Origin Access Control**: To control access to the S3 bucket from CloudFront.
3. **AWS CloudFront Distribution**: To distribute the video content globally.
4. **AWS Route53 Zone**: To manage DNS records for the video streaming site.
5. **AWS Route53 Record**: To create a DNS record pointing to the CloudFront distribution.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name = "Video Content Bucket"
  }
}

resource "aws_cloudfront_origin_access_control" "video_content_oac" {
  name                              = "video-content-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "never"
  signing_protocol                  = "sigv4"

  tags = {
    Name = "Video Content Origin Access Control"
  }
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled = true

  origin {
    domain_name              = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.video_content_oac.id
    origin_id                = "myS3Origin"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"
    viewer_protocol_policy = "redirect-to-https"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name = "Video Content Distribution"
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming-site.com"

  tags = {
    Name = "Video Streaming Zone"
  }
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_cloudfront_distribution.video_content_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_content_distribution.hosted_zone_id
    evaluate_target_health = true
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

### Explanation

- **AWS Provider**: Configured to use the `us-east-1` region.
- **S3 Bucket**: Created with a private ACL and a unique name generated using `random_string`.
- **CloudFront Origin Access Control**: Set up to control access to the S3 bucket from CloudFront.
- **CloudFront Distribution**: Configured to distribute the video content from the S3 bucket, with a default cache behavior and a viewer certificate.
- **Route53 Zone**: Created for the video streaming site domain.
- **Route53 Record**: Set up as an alias record pointing to the CloudFront distribution.

This configuration ensures that the video content is securely stored in S3, distributed globally via CloudFront, and accessible via a custom domain managed by Route53.

