provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.4.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.5.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_3" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.6.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_security_group" "main_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "main_sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main_vpc.cidr_block]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "app_lb" {
  name            = "app_lb"
  internal        = false
  load_balancer_type = "application"
  security_groups = [aws_security_group.main_sg.id]
  subnets         = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id, aws_subnet.subnet_3.id]

  subnet_mapping {
    subnet_id = aws_subnet.subnet_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_2.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_3.id
  }
}

resource "aws_lb_target_group" "http_target_group" {
  name     = "http_target_group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main_vpc.id
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.app_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.http_target_group.arn
  }
}

resource "aws_lb_target_group_attachment" "ec2_instance_attachment" {
  target_group_arn = aws_lb_target_group.http_target_group.arn
  target_id        = "i-1234567890abcdef0"  # Replace with a valid EC2 instance ID
  port             = 80
}

resource "aws_route53_zone" "video_stream_zone" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "lb_alias_record" {
  zone_id = aws_route53_zone.video_stream_zone.zone_id
  name    = "lb.test-video-stream.com"
  type    = "A"

  alias {
    name                   = aws_lb.app_lb.dns_name
    zone_id                = aws_lb.app_lb.zone_id
    evaluate_target_health = true
  }
}
