Below is the Terraform HCL program that sets up a VPC with public subnets, and security groups for database access. It also creates a PostgreSQL database instance within the VPC, accessible and secured by a designated security group.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "db_security_group"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lightsail_database" "postgres_db" {
  relational_database_name = "postgres-db"
  availability_zone        = "us-east-1a"
  master_database_name     = "mydb"
  master_password          = "securepassword"
  master_username          = "admin"
  blueprint_id             = "postgres_12"
  bundle_id                = "micro_1_0"
  tags = {
    Name = "postgres-db"
  }
}
```

