LLM Output #0:
Below is a complete Terraform HCL program that provisions a secure PostgreSQL database instance within a specified AWS VPC, leveraging AWS services like RDS, subnets, and KMS for encryption. It sets up a custom parameter group for PostgreSQL settings, and a security group to manage access. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be deployed"
  default     = "vpc-12345678"  # Replace with your VPC ID
}

variable "subnet_ids" {
  description = "List of subnet IDs where the RDS instance will be deployed"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
}

resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for encrypting the PostgreSQL database"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_iam_role" "rds_kms_key_access" {
  name = "rds-kms-key-access"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "rds_kms_key_access_policy" {
  name = "rds-kms-key-access-policy"
  role = aws_iam_role.rds_kms_key_access.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Effect = "Allow"
        Resource = aws_kms_key.db_encryption_key.arn
      }
    ]
  })
}

resource "aws_security_group" "postgresql_sg" {
  name        = "postgresql-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for your security requirements
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "postgresql_custom_params" {
  name   = "postgresql-custom-params"
  family = "postgres13"

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  parameter {
    name  = "shared_buffers"
    value = "256MB"
  }
}

resource "aws_db_instance" "secure_postgresql_db" {
  instance_class       = "db.t3.micro"
  engine               = "postgres"
  engine_version       = "13.7"
  allocated_storage    = 20
  storage_encrypted    = true
  kms_key_id           = aws_kms_key.db_encryption_key.arn
  multi_az             = true
  backup_retention_period = 7
  db_subnet_group_name = "default"  # Ensure this matches your DB subnet group name
  parameter_group_name = aws_db_parameter_group.postgresql_custom_params.name
  vpc_security_group_ids = [aws_security_group.postgresql_sg.id]
  identifier           = "secure-postgresql-db"

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}
```

This Terraform configuration sets up the necessary resources to deploy a secure PostgreSQL database instance within an AWS VPC. It includes an IAM role with the necessary permissions to access the KMS key, a security group to manage access, a custom parameter group for PostgreSQL settings, and the RDS instance itself configured with encryption and multi-AZ deployment for high availability.

