Below is a complete Terraform HCL program that sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a 500 GB 5.7 MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
