```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database and proxy will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_id" {
  description = "The ID of the subnet where the database and proxy will be deployed."
  default     = "subnet-12345678"
}

variable "db_instance_class" {
  description = "The instance class for the PostgreSQL database."
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "The name of the database."
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database."
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database."
  default     = "securepassword"
}

resource "aws_db_instance" "postgres_db_instance" {
  instance_class           = var.db_instance_class
  engine                   = "postgres"
  engine_version           = "13"
  allocated_storage        = 20
  allow_major_version_upgrade = true
  auto_minor_version_upgrade = true
  db_name                  = var.db_name
  username                 = var.db_username
  password                 = var.db_password
  publicly_accessible      = false
  vpc_security_group_ids   = [aws_security_group.db_proxy_sg.id]
  db_subnet_group_name     = "default"
}

resource "aws_iam_role" "db_proxy_role" {
  name = "db-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_security_group" "db_proxy_sg" {
  name        = "db-proxy-sg"
  description = "Security group for the DB proxy"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_proxy" "postgres_db_proxy" {
  name                   = "postgres-db-proxy"
  engine_family          = "POSTGRESQL"
  role_arn               = aws_iam_role.db_proxy_role.arn
  vpc_subnet_ids         = [var.subnet_id]
  vpc_security_group_ids = [aws_security_group.db_proxy_sg.id]

  auth {
    auth_scheme = "SECRET"
    username    = var.db_username
    secret_arn  = "arn:aws:secretsmanager:us-west-2:123456789012:secret:mydatabase-secret"
  }
}
```

