LLM Output #0:
### Description
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the creation of a VPC, subnets, security groups, IAM roles, and a Secrets Manager secret for secure credential storage. The RDS cluster has a backup retention period of 5 days and a preferred backup window from 7 AM to 9 AM.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC
resource "aws_vpc" "rds_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "rds-vpc"
  }
}

# Subnets
resource "aws_subnet" "rds_subnet_public_1" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "rds-subnet-public-1"
  }
}

resource "aws_subnet" "rds_subnet_public_2" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "rds-subnet-public-2"
  }
}

# Security Group
resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.rds_vpc.id
  name   = "rds-security-group"
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "rds-security-group"
  }
}

# IAM Role
resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
  tags = {
    Name = "rds-iam-role"
  }
}

# IAM Policy
resource "aws_iam_policy" "rds_iam_policy" {
  name        = "rds-iam-policy"
  description = "Policy for RDS Aurora MySQL cluster"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "rds-iam-policy"
  }
}

# IAM Role Policy Attachment
resource "aws_iam_role_policy_attachment" "rds_iam_role_policy_attachment" {
  policy_arn = aws_iam_policy.rds_iam_policy.arn
  role       = aws_iam_role.rds_iam_role.name
}

# Secrets Manager Secret
resource "aws_secretsmanager_secret" "rds_secret" {
  name = "rds-secret"
  description = "Secret for RDS Aurora MySQL cluster"
  tags = {
    Name = "rds-secret"
  }
}

# RDS Aurora MySQL Cluster
resource "aws_rds_cluster" "rds_cluster" {
  engine                = "aurora-mysql"
  engine_version        = "8.0.mysql_aurora.3.02.0"
  cluster_identifier    = "aurora-cluster-demo"
  master_username       = "admin"
  master_password       = "password123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name  = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  iam_roles             = [aws_iam_role.rds_iam_role.arn]
  tags = {
    Name = "aurora-cluster-demo"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = [aws_subnet.rds_subnet_public_1.id, aws_subnet.rds_subnet_public_2.id]
  tags = {
    Name = "rds-subnet-group"
  }
}

# DB Proxy
resource "aws_db_proxy" "rds_db_proxy" {
  name                   = "rds-db-proxy"
  engine_family          = "MYSQL"
  auth {
    auth_scheme    = "SECRETS"
    description    = "Proxy authentication"
    iam_auth       = "DISABLED"
    secret_arn     = aws_secretsmanager_secret.rds_secret.arn
    username       = "admin"
  }
  role_arn               = aws_iam_role.rds_iam_role.arn
  vpc_subnet_ids         = [aws_subnet.rds_subnet_public_1.id, aws_subnet.rds_subnet_public_2.id]
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  tags = {
    Name = "rds-db-proxy"
  }
}

# DB Proxy Target Group
resource "aws_db_proxy_target_group" "rds_db_proxy_target_group" {
  db_proxy_name = aws_db_proxy.rds_db_proxy.name
  target_group_name = "rds-db-proxy-target-group"
  tags = {
    Name = "rds-db-proxy-target-group"
  }
}

# DB Proxy Endpoint
resource "aws_db_proxy_endpoint" "rds_db_proxy_endpoint" {
  db_proxy_name         = aws_db_proxy.rds_db_proxy.name
  db_proxy_endpoint_name = "rds-db-proxy-endpoint"
  vpc_subnet_ids         = [aws_subnet.rds_subnet_public_1.id, aws_subnet.rds_subnet_public_2.id]
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  tags = {
    Name = "rds-db-proxy-endpoint"
  }
}
