### Description
This Terraform configuration sets up a basic Amazon Lightsail environment, including a bucket, a distribution, an instance, and a key pair. The distribution is configured to use the bucket as its origin.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lightsail_bucket" "lightsail_bucket" {
  name      = "my-lightsail-bucket"
  bundle_id = "small_1_0"
}

resource "aws_lightsail_distribution" "lightsail_distribution" {
  name      = "my-lightsail-distribution"
  bundle_id = "small_1_0"

  origin {
    name        = aws_lightsail_bucket.lightsail_bucket.name
    region_name = "us-east-1"
  }

  default_cache_behavior {
    behavior = "cache"
  }

  cache_behavior_settings {
    allowed_http_methods = "GET,HEAD,OPTIONS,PUT,PATCH,POST,DELETE"
    cached_http_methods  = "GET,HEAD"
    default_ttl          = 86400
    maximum_ttl          = 31536000
    minimum_ttl          = 0
  }
}

resource "aws_lightsail_instance" "lightsail_instance" {
  availability_zone = "us-east-1b"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_3_0"
  name              = "my-lightsail-instance"
}

resource "aws_lightsail_key_pair" "lightsail_key_pair" {
  name = "my-lightsail-key-pair"
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **Lightsail Bucket**: A Lightsail bucket named `my-lightsail-bucket` is created with the `small_1_0` bundle.
3. **Lightsail Distribution**: A Lightsail distribution named `my-lightsail-distribution` is created with the same `small_1_0` bundle. It uses the previously created bucket as its origin.
