  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "test_lb_tf_sg" {
  name        = "test-lb-tf-sg"
  description = "Security group for test-lb-tf"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "test_lb_tf" {
  name               = "test-lb-tf"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.test_lb_tf_sg.id]

  subnet_mapping {
    subnet_id = aws_subnet.test_lb_tf_subnet1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.test_lb_tf_subnet2.id
  }

  enable_deletion_protection = true
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
