### Description
This Terraform program creates an Application Load Balancer (ALB) with two subnets and specifies Elastic IPs for each subnet. The ALB is associated with a target group. The configuration includes the necessary resources such as VPC, subnets, Elastic IPs, and IAM roles.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "example-vpc"
  }
}

# Create two subnets
resource "aws_subnet" "example_subnet1" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "example-subnet1"
  }
}

resource "aws_subnet" "example_subnet2" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "example-subnet2"
  }
}

# Create Elastic IPs
resource "aws_eip" "example_eip1" {
  vpc = true
  tags = {
    Name = "example-eip1"
  }
}

resource "aws_eip" "example_eip2" {
  vpc = true
  tags = {
    Name = "example-eip2"
  }
}

# Create an Application Load Balancer
resource "aws_lb" "example_lb" {
  name               = "example-alb"
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id     = aws_subnet.example_subnet1.id
    allocation_id = aws_eip.example_eip1.id
  }

  subnet_mapping {
    subnet_id     = aws_subnet.example_subnet2.id
    allocation_id = aws_eip.example_eip2.id
  }

  tags = {
    Name = "example-alb"
  }
}

# Create a Target Group
resource "aws_lb_target_group" "example_lb_target_group" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-target-group"
  }
}

# Associate the Target Group with the Load Balancer
resource "aws_lb_listener" "example_lb_listener" {
  load_balancer_arn = aws_lb.example_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example_lb_target_group.arn
  }
}
```

This Terraform configuration sets up an Application Load Balancer with two subnets, each associated with an Elastic IP. The load balancer is configured to forward traffic to a target group. The VPC, subnets, Elastic IPs, and IAM roles are all created within the same Terraform program.

