### Description
This Terraform configuration sets up an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The configuration includes the following resources:
- **aws_lb_target_group**: Defines the target group for the load balancer.
- **aws_lb**: Creates the Application Load Balancer.
- **aws_security_group**: Sets up a security group for the load balancer.
- **aws_subnet**: Specifies the subnet where the load balancer will be deployed.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "lb_sg" {
  name        = "lb-sg"
  description = "Security group for the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "lb_target_group" {
  name        = "my-target-group"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"
}

resource "aws_lb" "lb" {
  name            = "my-load-balancer"
  internal        = false
  load_balancer_type = "application"
  security_groups = [aws_security_group.lb_sg.id]

  subnet_mapping {
    subnet_id = aws_subnet.subnet.id
  }

  tags = {
    Name = "My Load Balancer"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lb_target_group.arn
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnet**: A VPC and a subnet are created to host the load balancer.
- **Security Group**: A security group is defined to allow HTTP traffic on port 80.
- **Target Group**: An Application Load Balancer target group is created to manage the instances.
- **Load Balancer**: An Application Load Balancer is created and associated with the subnet and security group.
- **Listener**: A listener is added to the load balancer to forward incoming HTTP traffic to the target group.

This configuration ensures that the load balancer is properly set up to forward traffic to the specified instances in the target group.

