### Description
This Terraform program creates an Application Load Balancer (ALB) with an HTTP listener that uses the `authenticate-cognito` action to authenticate users via Amazon Cognito. The program includes the necessary resources for the ALB, listener, and Cognito components.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Create subnets
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(["us-west-2a", "us-west-2b"], count.index)
  map_public_ip_on_launch = true
}

# Create a security group for the ALB
resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create the Application Load Balancer
resource "aws_lb" "front_end" {
  name               = "front-end-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = true
}

# Create a Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name = "my-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  schema {
    name                 = "email"
    attribute_data_type  = "String"
    mutable              = true
    required             = true
    string_attribute_constraints {
      min_length = 6
    }
  }
}

# Create a Cognito User Pool Client
resource "aws_cognito_user_pool_client" "client" {
  name                = "my-app-client"
  user_pool_id        = aws_cognito_user_pool.pool.id
  generate_secret     = true
  allowed_oauth_flows = ["code", "implicit"]

  allowed_oauth_scopes = [
    "phone",
    "email",
    "openid",
    "profile",
    "aws.cognito.signin.user.admin"
  ]

  callback_urls         = ["https://www.example.com/callback"]
  logout_urls           = ["https://www.example.com/logout"]
  supported_identity_providers = ["COGNITO"]
}

# Create a Cognito User Pool Domain
resource "aws_cognito_user_pool_domain" "domain" {
  domain       = "my-user-pool-domain"
  user_pool_id = aws_cognito_user_pool.pool.id
}

# Create a listener for the ALB
resource "aws_lb_listener" "front_end" {
  load_balancer_arn = aws_lb.front_end.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.client.id
      user_pool_domain    = aws_cognito_user_pool_domain.domain.domain
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.front_end.arn
  }
}

# Create a target group for the ALB
resource "aws_lb_target_group" "front_end" {
  name     = "front-end-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}
```

This Terraform configuration sets up an Application Load Balancer with an HTTP listener that uses Cognito for authentication. It includes the necessary resources for the ALB, listener, and Cognito components, ensuring that all dependencies are correctly established.

