### Description
This Terraform configuration creates a Gateway Load Balancer (GLB) in an AWS VPC. The configuration includes the creation of a VPC, a subnet, an internet gateway, and the GLB itself along with its target group. The GLB is configured to use the specified subnet and has a target group with specific settings.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "main-subnet"
  }
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
  tags = {
    Name = "main-igw"
  }
}

resource "aws_lb" "main_glb" {
  name               = "main-glb"
  load_balancer_type = "gateway"
  subnet_mapping {
    subnet_id = aws_subnet.main_subnet.id
  }
  tags = {
    Name = "main-glb"
  }
}

resource "aws_lb_target_group" "main_glb_target_group" {
  name        = "main-glb-target-group"
  port        = 80
  protocol    = "TCP"
  vpc_id      = aws_vpc.main_vpc.id
  target_type = "ip"
  target_failover {
    on_deregistration = "rebalance"
    on_unhealthy      = "rebalance"
  }
  tags = {
    Name = "main-glb-target-group"
  }
}
```

This configuration sets up a basic infrastructure for a Gateway Load Balancer in AWS, including the necessary VPC, subnet, and internet gateway components. The GLB is configured to use the specified subnet, and the target group is set up with the required parameters.

