### Description
This Terraform configuration creates an Application Load Balancer (ALB) with an associated Target Group. The ALB is deployed in a public subnet and secured by a security group that allows HTTP traffic. The configuration includes the necessary resources and dependencies to ensure proper deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "lb_security_group" {
  name        = "alb-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "alb_target_group" {
  name        = "alb-target-group"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    enabled             = true
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    path                = "/"
  }
}

resource "aws_lb" "application_load_balancer" {
  name            = "application-load-balancer"
  internal        = false
  load_balancer_type = "application"
  security_groups = [aws_security_group.lb_security_group.id]

  subnet_mapping {
    subnet_id = aws_subnet.public_subnet.id
  }

  tags = {
    Name = "Application Load Balancer"
  }
}
```

This configuration sets up an Application Load Balancer with an associated Target Group in a public subnet. The security group allows HTTP traffic from any source, and the health check is configured to monitor the target instances.

