### Description
This Terraform configuration creates an AWS EFS File System with tags, along with a VPC, Subnet, and Security Group necessary for the EFS Mount Target. The EFS File System is tagged with a "Name" tag. The VPC, Subnet, and Security Group are configured to support the EFS Mount Target.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "EFS-VPC"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id            = aws_vpc.vpc.id
  availability_zone = "us-west-2a"
  cidr_block        = "10.0.1.0/24"

  tags = {
    Name = "EFS-Subnet"
  }
}

resource "aws_security_group" "security_group" {
  vpc_id = aws_vpc.vpc.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "EFS-SecurityGroup"
  }
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"

  tags = {
    Name = "MyEFSFileSystem"
  }
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.subnet.id
  security_groups = [aws_security_group.security_group.id]

  tags = {
    Name = "EFS-MountTarget"
  }
}
```

This configuration sets up the necessary AWS resources to create an EFS File System with tags, including a VPC, Subnet, and Security Group. The EFS Mount Target is associated with these resources, ensuring proper connectivity and security.

