  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }
}

resource "aws_efs_file_system_policy" "efs_file_system_policy" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.efs_file_system.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  vpc_id            = aws_vpc.vpc.id
  availability_zone = "us-west-2a"
  cidr_block        = "10.0.1.0/24"
}

resource "aws_security_group" "security_group" {
  vpc_id = aws_vpc.vpc.id
  name   = "efs-security-group"

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.subnet.id
  security_groups = [aws_security_group.security_group.id]
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **EFS File System**: An EFS file system is created with a lifecycle policy that transitions files to IA (Infrequent Access) storage class after 30 days.
3. **EFS File System Policy**: A policy is attached to the EFS file system to allow clients to mount and write to the file system over secure transport.
4. **VPC and Subnet**: A VPC and a subnet are created to provide the network infrastructure for the EFS mount target.
5. **Security Group**: A security group is created to allow inbound NFS traffic (port 2049) and outbound traffic.
6. **EFS Mount Target**: A mount target is created for the EFS file system in the specified subnet and security group.

