provider "aws" {
  region = "us-west-2"
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  encrypted      = true
}

resource "aws_efs_file_system_policy" "efs_file_system_policy" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  policy         = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.efs_file_system.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_vpc" "efs_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "efs_subnet" {
  vpc_id            = aws_vpc.efs_vpc.id
  availability_zone = "us-west-2a"
  cidr_block        = "10.0.1.0/24"
}

resource "aws_security_group" "efs_security_group" {
  vpc_id = aws_vpc.efs_vpc.id
  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.efs_subnet.id
  security_groups = [aws_security_group.efs_security_group.id]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **EFS File System**: An EFS file system is created with encryption enabled.
- **EFS File System Policy**: A policy is attached to the EFS file system allowing clients to mount and write to the file system over secure transport.
- **VPC and Subnet**: A VPC and a subnet are created to support the EFS mount target.
- **Security Group**: A security group is created to allow inbound and outbound traffic on port 2049 (NFS).
- **EFS Mount Target**: A mount target is created for the EFS file system in the specified subnet and security group.

