This Terraform configuration sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled. It includes an internet gateway and a route table for outbound internet access. All resources are tagged with a variable name provided during deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name to tag the VPC and related resources with"
  default     = "my-vpc"
}

resource "aws_vpc" "dedicated_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "dedicated"

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.dedicated_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.dedicated_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route" "route_to_internet" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id

  tags = {
    Name = var.vpc_name
  }
}
```

